def weekday_name(d):
    n = d.day()
    if n == 6:
        return "Sunday"
    elif n == 5:
        return "Monday"
    elif n == 4:
        return "Tuesday"
    elif n == 3:
        return "Wednesday"
    elif n == 2:
        return "Thursday"
    elif n == 1:
        return "Friday"
    else:
        return "Saturday"
